CREATE OR REPLACE PACKAGE json_demo AS
  TYPE t_user IS RECORD (
    name VARCHAR2(4000),
    age NUMBER
  );
  FUNCTION pack(p_u IN t_user) RETURN JSON;
  FUNCTION unpack_name(p_j IN JSON) RETURN VARCHAR2;
  FUNCTION audit_event(p_action IN VARCHAR2, p_who IN VARCHAR2) RETURN JSON;
  FUNCTION list_things(p_a IN NUMBER, p_b IN NUMBER, p_c IN NUMBER) RETURN JSON;
  FUNCTION extract_text(p_j IN JSON, p_path IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION extract_number(p_j IN JSON, p_path IN VARCHAR2) RETURN NUMBER;
  FUNCTION has_path(p_j IN JSON, p_path IN VARCHAR2) RETURN BOOLEAN;
